/* Sirah events 45-77 (eras 5-8). [Malay, English]. Own-words retelling of Ar-Raheeq al-Makhtum. */
SIRAH.push(
{id:"s45",n:45,e:5,y:619.1,age:49,pl:"makkah",sc:"birth",
 w:["Tahun ke-10 kenabian","Year 10 of prophethood"],
 t:["Rundingan terakhir Quraisy dengan Abu Talib","Quraysh's last talks with Abu Talib"],
 f:["Selepas pemulauan berakhir, Abu Talib jatuh sakit tenat. Pembesar Quraisy, antaranya Utbah, Syaibah, Abu Jahal, Umayyah bin Khalaf dan Abu Sufyan, datang menemuinya buat kali terakhir. Mereka meminta Abu Talib mengambil janji antara mereka dan anak saudaranya: Baginda membiarkan agama mereka dan mereka membiarkan agamanya.\nRasulullah ﷺ menjawab bahawa Baginda hanya meminta satu kalimah daripada mereka, yang dengannya mereka akan menguasai bangsa Arab dan bangsa lain tunduk kepada mereka: “La ilaha illallah.” Mereka bertepuk tangan kehairanan dan bangun sambil berkata: “Adakah dia menjadikan tuhan-tuhan itu satu Tuhan sahaja?”",
   "After the boycott ended, Abu Talib fell gravely ill. The leaders of Quraysh, among them 'Utbah, Shaybah, Abu Jahl, Umayyah ibn Khalaf and Abu Sufyan, came to him one last time. They asked Abu Talib to settle a pact between them and his nephew: he would leave their religion alone and they would leave his.\nThe Prophet ﷺ replied that he asked them for just one word, through which they would lead the Arabs and others would follow them: “La ilaha illallah.” They clapped their hands in disbelief and got up saying: “Has he made the gods into one God?”"],
 l:[["Tauhid tidak boleh dikompromi demi perdamaian palsu.","The oneness of Allah cannot be traded for a false peace."]],
 p:["abutalib","abujahal","abusufyan"],s:"The Final Phase of the Diplomacy of Negotiation, p.52|Perwakilan Quraisy menemui Abu Talib untuk kali terakhir"},

{id:"s46",n:46,e:5,m:1,y:619.2,age:50,pl:"makkah",sc:"abwa",
 w:["Rejab, tahun ke-10 kenabian","Rajab, year 10 of prophethood"],
 t:["Abu Talib wafat","Abu Talib dies"],
 f:["Abu Talib wafat enam bulan selepas keluar dari lembah pemulauan. Ketika beliau hampir wafat, Rasulullah ﷺ berada di sisinya dan merayu: “Wahai bapa saudaraku, ucapkanlah La ilaha illallah, satu kalimah yang akan aku jadikan hujah untukmu di sisi Allah.” Abu Jahal dan Abdullah bin Abi Umayyah yang turut hadir mengingatkannya tentang agama Abdul Muttalib. Akhirnya Abu Talib wafat dalam agama datuknya.\nRasulullah ﷺ sangat berduka. Selama lebih empat puluh tahun Abu Talib menjaga dan melindungi Baginda. Dengan wafatnya, Quraisy mula berani menyakiti Baginda secara terbuka.",
   "Abu Talib died six months after leaving the valley of the boycott. As he lay dying, the Prophet ﷺ was at his side, pleading: “O my uncle, say La ilaha illallah, a word I can use to plead for you before Allah.” Abu Jahl and 'Abdullah ibn Abi Umayyah, who were there, reminded him of the religion of 'Abdul-Muttalib. In the end Abu Talib died upon the religion of his forefathers.\nThe Prophet ﷺ was deeply grieved. For more than forty years Abu Talib had cared for and protected him. With his death, Quraysh began to harm him openly."],
 k:["Abu Talib, bapa saudara yang menjaga Nabi ﷺ sejak kecil, meninggal dunia. Nabi ﷺ sangat sedih kerana Abu Talib sentiasa melindunginya.","Abu Talib, the uncle who had cared for the Prophet ﷺ since he was a boy, passed away. The Prophet ﷺ was very sad, because Abu Talib had always protected him."],
 l:[["Hidayah milik Allah. Kasih sayang manusia tidak dapat memberikannya.","Guidance belongs to Allah. Human love cannot give it."],["Hargailah orang yang melindungi kita.","Value those who protect us."]],
 hd:[{r:"Sahih al-Bukhari 3884",m:["Al-Musayyib meriwayatkan Rasulullah ﷺ merayu Abu Talib mengucapkan La ilaha illallah ketika hampir wafat.","Al-Musayyab narrated that the Prophet ﷺ urged Abu Talib to say La ilaha illallah as he was dying."]}],
 o:["Riwayat lain menyebut Abu Talib wafat pada bulan Ramadan, tiga hari sebelum Khadijah.","Another report says Abu Talib died in Ramadan, three days before Khadijah."],
 p:["abutalib","abujahal"],s:"Abu Talib's Death, p.52|Tahun perkabungan"},

{id:"s47",n:47,e:5,m:1,y:619.3,age:50,pl:"makkah",sc:"sunset",
 w:["Ramadan, tahun ke-10 kenabian (619)","Ramadan, year 10 of prophethood (619)"],
 t:["Khadijah (r.a.) wafat","Khadijah (r.a.) passes away"],
 f:["Kira-kira dua atau tiga bulan selepas Abu Talib, Khadijah (r.a.) pula wafat pada bulan Ramadan tahun kesepuluh kenabian, ketika berusia 65 tahun. Rasulullah ﷺ ketika itu berusia 50 tahun.\nKhadijah ialah orang pertama yang beriman, yang membenarkan Baginda ketika orang lain mendustakan, membantu dengan hartanya ketika orang lain enggan, dan melahirkan anak-anak Baginda. Jibril pernah membawa salam Allah kepadanya dan berita gembira tentang sebuah rumah di syurga yang tiada bising dan tiada letih.\nKerana dua kehilangan besar ini, tahun itu dikenali sebagai ‘Am al-Huzn, Tahun Dukacita.",
   "About two or three months after Abu Talib, Khadijah (r.a.) passed away in Ramadan of the tenth year of prophethood, aged 65. The Prophet ﷺ was then 50.\nKhadijah was the first to believe. She trusted him when others called him a liar, gave her wealth when others held back, and bore his children. Jibril once brought her greetings of peace from Allah and the good news of a house in Paradise with no noise and no weariness.\nBecause of these two great losses, that year became known as 'Am al-Huzn, the Year of Grief."],
 k:["Tidak lama kemudian, isteri tercinta Nabi ﷺ, Khadijah, juga meninggal dunia. Kerana itu tahun ini dipanggil Tahun Dukacita. Allah menjanjikan Khadijah sebuah rumah yang indah di syurga.","Soon after, the Prophet's ﷺ beloved wife Khadijah also passed away. That is why this year is called the Year of Grief. Allah promised Khadijah a beautiful house in Paradise."],
 l:[["Kesetiaan seorang isteri diingati oleh Rasulullah ﷺ sepanjang hayatnya.","The Prophet ﷺ remembered a wife's loyalty all his life."],["Para nabi juga diuji dengan kesedihan.","The prophets too were tested with sorrow."]],
 hd:[{r:"Sahih al-Bukhari 3820",m:["Jibril berkata: “Sampaikan kepadanya salam daripada Tuhannya dan daripadaku, dan khabarkan kepadanya berita gembira tentang sebuah rumah di syurga.”","Jibril said: “Convey to her greetings of peace from her Lord and from me, and give her the good news of a house in Paradise.”"]}],
 p:["khadijah"],s:"Khadijah Passes Away, p.52|Khadijah kembali ke rahmatullah"},

{id:"s48",n:48,e:5,y:619.35,age:50,pl:"makkah",sc:"birth",
 w:["Syawal, tahun ke-10 kenabian","Shawwal, year 10 of prophethood"],
 t:["Perkahwinan dengan Saudah (r.a.)","Marriage to Sawdah (r.a.)"],
 f:["Saudah binti Zam'ah ialah antara orang terawal memeluk Islam dan pernah berhijrah ke Habsyah bersama suaminya, as-Sakran bin Amr. Suaminya wafat, dan beliau menjadi balu. Selepas idahnya selesai, Rasulullah ﷺ meminang dan mengahwininya pada bulan Syawal tahun kesepuluh kenabian.\nSaudah ialah isteri pertama yang dikahwini Rasulullah ﷺ selepas Khadijah. Beliau menjaga rumah tangga dan anak-anak Baginda. Bertahun-tahun kemudian, beliau menghadiahkan gilirannya kepada Aisyah.",
   "Sawdah bint Zam'ah was among the earliest to accept Islam and had emigrated to Abyssinia with her husband, as-Sakran ibn 'Amr. Her husband died and she was left a widow. After her waiting period, the Prophet ﷺ proposed to her and married her in Shawwal of the tenth year of prophethood.\nSawdah was the first wife he married after Khadijah. She looked after his home and his daughters. Years later she gave her turn to 'A'ishah."],
 l:[["Menjaga balu orang beriman ialah kemuliaan.","Caring for a believing widow is an honour."]],
 p:["saudah"],s:"His Marriage to Sawdah, p.52|Secebis ulasan mengenai perkahwinan Rasulullah"},

{id:"s49",n:49,e:5,m:1,y:619.42,age:50,pl:"taif",sc:"taif",
 w:["Syawal, tahun ke-10 kenabian (akhir Mei atau awal Jun 619)","Shawwal, year 10 of prophethood (late May or early June 619)"],
 t:["Perjalanan ke Ta'if & doa Baginda","The journey to Ta'if and his prayer"],
 f:["Rasulullah ﷺ berjalan kaki ke Ta'if, kira-kira 60 kilometer dari Makkah, bersama Zaid bin Harithah, untuk menyeru kabilah Thaqif. Tiga bersaudara pembesar Thaqif menolak Baginda dengan kata-kata yang menghina. Baginda tinggal sepuluh hari menyeru orang di sana, tetapi tiada yang menerima.\nAkhirnya mereka menghasut orang ramai mengejar Baginda keluar sambil melontar batu hingga kaki Baginda berdarah. Zaid cuba melindungi Baginda hingga kepalanya luka. Baginda berlindung di sebuah kebun anggur dan berdoa: “Ya Allah, kepada-Mu aku mengadu lemahnya kekuatanku... Jika Engkau tidak murka kepadaku, aku tidak peduli.”\nPemilik kebun itu menghantar anggur melalui hamba mereka, Addas, seorang Nasrani dari Ninawa. Apabila Baginda menyebut Nabi Yunus (a.s.), Addas mencium tangan Baginda.\nDalam perjalanan pulang, di Qarn al-Manazil, Jibril datang bersama malaikat gunung yang menawarkan untuk menghimpit penduduk Makkah di antara dua gunung. Baginda menolak dan berkata: “Aku berharap Allah mengeluarkan daripada keturunan mereka orang yang menyembah Allah.”",
   "The Prophet ﷺ walked to Ta'if, about 60 kilometres from Makkah, with Zayd ibn Harithah, to call the tribe of Thaqif. Three brothers who led Thaqif turned him away with insults. He stayed ten days calling people there, but no one accepted.\nIn the end they set the crowds on him, chasing him out and throwing stones until his feet bled. Zayd tried to shield him and was wounded in the head. He sheltered in a vineyard and prayed: “O Allah, to You I complain of my weakness... If You are not angry with me, I do not care.”\nThe owners of the vineyard sent grapes with their servant 'Addas, a Christian from Nineveh. When the Prophet mentioned Yunus (a.s.), 'Addas kissed his hands.\nOn the way back, at Qarn al-Manazil, Jibril came with the angel of the mountains, who offered to crush Makkah between its two mountains. He refused, saying: “I hope Allah will bring from their descendants people who worship Allah.”"],
 k:["Nabi ﷺ pergi ke bandar Ta'if untuk mengajak orang menyembah Allah. Penduduknya tidak baik dan melontar batu. Tetapi Nabi ﷺ memaafkan mereka dan berdoa supaya anak cucu mereka menyembah Allah.","The Prophet ﷺ went to the town of Ta'if to invite people to worship Allah. The people were unkind and threw stones. But the Prophet ﷺ forgave them and prayed that their children would worship Allah."],
 l:[["Memaafkan ketika mampu membalas ialah akhlak tertinggi.","Forgiving when able to retaliate is the highest character."],["Mengadu hanya kepada Allah ketika paling lemah.","In your weakest moment, complain to Allah alone."],["Dakwah memerlukan harapan jauh ke hadapan, hingga generasi akan datang.","Calling to Allah needs hope that reaches to future generations."]],
 hd:[{r:"Sahih al-Bukhari 3231",m:["Aisyah (r.a.) bertanya sama ada ada hari yang lebih berat daripada Uhud. Baginda menceritakan hari di Ta'if dan malaikat gunung.","'A'ishah (r.a.) asked if any day had been harder than Uhud. He told of the day at Ta'if and the angel of the mountains."]}],
 p:["zaid","addas"],s:"The Third Phase: Calling unto Islam beyond Makkah, p.82|Seruan Islam keluar Mekah"},

{id:"s50",n:50,e:5,y:619.44,age:50,pl:"nakhlah",sc:"valley",
 w:["Dalam perjalanan pulang dari Ta'if","On the way back from Ta'if"],
 t:["Jin mendengar al-Quran di Nakhlah","The jinn listen to the Quran at Nakhlah"],
 f:["Selepas Qarn al-Manazil, Rasulullah ﷺ berhenti beberapa hari di lembah Nakhlah. Ketika Baginda membaca al-Quran dalam solat, Allah menghantar sekumpulan jin yang mendengar dengan senyap. Selepas selesai, mereka kembali kepada kaum mereka sebagai pemberi peringatan, lalu beriman.\nPeristiwa ini disebut dalam Surah al-Ahqaf dan Surah al-Jin. Ketika manusia di Ta'if menolak, Allah menunjukkan bahawa risalah Baginda diterima oleh makhluk lain, satu penghiburan yang besar.",
   "After Qarn al-Manazil, the Prophet ﷺ stopped for a few days in the valley of Nakhlah. As he recited the Quran in prayer, Allah sent a group of jinn who listened in silence. When he finished, they went back to their people as warners, and believed.\nThis is mentioned in Surah al-Ahqaf and Surah al-Jinn. When the people of Ta'if refused, Allah showed that his message was being received by other beings, a great comfort."],
 l:[["Pertolongan Allah sering datang dari arah yang tidak disangka.","Allah's help often comes from where one least expects."]],
 ay:[{r:"al-Ahqaf 46:29",ar:"وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِّنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ",m:["Dan ingatlah ketika Kami hadapkan kepadamu sekumpulan jin yang mendengar al-Quran.","And when We directed to you a group of jinn, listening to the Quran."]}],
 s:"The Third Phase: Calling unto Islam beyond Makkah, p.82|Seruan Islam keluar Mekah"},

{id:"s51",n:51,e:5,y:619.5,age:50,pl:"makkah",sc:"kaabah",
 w:["Zulkaedah, tahun ke-10 kenabian","Dhul-Qa'dah, year 10 of prophethood"],
 t:["Pulang ke Makkah dengan perlindungan Mut'im","Back to Makkah under Mut'im's protection"],
 f:["Tanpa Abu Talib, Rasulullah ﷺ memerlukan perlindungan untuk masuk semula ke Makkah. Baginda menghantar utusan kepada beberapa pembesar. Al-Akhnas bin Syariq dan Suhail bin Amr menolak. Al-Mut'im bin 'Adi bersetuju.\nAl-Mut'im dan anak-anaknya memakai senjata dan berdiri di sisi Kaabah sambil mengumumkan bahawa mereka melindungi Muhammad ﷺ. Baginda pun tawaf dan bersolat, kemudian pulang ke rumah dengan selamat. Rasulullah ﷺ tidak melupakan jasa al-Mut'im. Selepas Badar, Baginda berkata bahawa jika al-Mut'im masih hidup dan meminta tawanan dilepaskan, Baginda akan melepaskan mereka kerananya.",
   "Without Abu Talib, the Prophet ﷺ needed protection to re-enter Makkah. He sent word to several chiefs. Al-Akhnas ibn Shariq and Suhayl ibn 'Amr refused. Al-Mut'im ibn 'Adi agreed.\nAl-Mut'im and his sons put on their weapons and stood by the Kaabah, announcing that Muhammad ﷺ was under their protection. He performed tawaf and prayed, then went home safely. He never forgot al-Mut'im's kindness. After Badr he said that had al-Mut'im been alive and asked for the captives, he would have freed them for his sake."],
 l:[["Mengenang jasa orang walaupun dia tidak seagama.","Remember a kindness, even from someone of another faith."]],
 hd:[{r:"Sahih al-Bukhari 3139",m:["Baginda bersabda tentang tawanan Badar: “Jika al-Mut'im bin 'Adi masih hidup lalu bercakap kepadaku tentang mereka, nescaya aku lepaskan mereka kerananya.”","He said of the Badr captives: “Had al-Mut'im ibn 'Adi been alive and spoken to me about them, I would have freed them for him.”"]}],
 p:["mutim"],s:"The Third Phase: Calling unto Islam beyond Makkah, p.82|Seruan Islam keluar Mekah"},

{id:"s52",n:52,e:6,y:619.8,age:"49–52",pl:"mina",sc:"market",
 w:["Musim haji, tahun ke-10 hingga ke-13 kenabian","Hajj seasons, years 10 to 13 of prophethood"],
 t:["Menyeru kabilah-kabilah pada musim haji","Calling the tribes at the pilgrim season"],
 f:["Pada setiap musim haji dan di pasar-pasar seperti 'Ukaz, Majannah dan Dzul Majaz, Rasulullah ﷺ mendatangi khemah kabilah satu demi satu. Baginda mengajak mereka kepada Allah dan meminta perlindungan supaya Baginda dapat menyampaikan risalah.\nAntara kabilah yang didatangi ialah Bani Kalb, Bani Hanifah, Bani 'Amir bin Sa'sa'ah dan Syaiban bin Tha'labah. Ada yang menolak dengan kasar, ada yang mahu kuasa selepas Baginda, ada yang bimbang dengan Parsi. Abu Lahab sering mengekori dari belakang dan berkata: “Jangan percaya kepadanya.” Namun Baginda tidak berputus asa.",
   "In every Hajj season, and at markets such as 'Ukaz, Majannah and Dhul-Majaz, the Prophet ﷺ went from tent to tent. He invited each tribe to Allah and asked for protection so he could convey the message.\nAmong those he visited were Banu Kalb, Banu Hanifah, Banu 'Amir ibn Sa'sa'ah and Shayban ibn Tha'labah. Some refused rudely, some wanted power after him, some feared Persia. Abu Lahab often walked behind him saying: “Do not believe him.” Still he never gave up."],
 l:[["Usaha berterusan walaupun ditolak berkali-kali.","Keep trying even after being refused many times."]],
 p:["abulahab"],s:"Islam Being Introduced to Arabian Tribes, p.82|Memperkenalkan Islam kepada qabilah dan individu tertentu"},

{id:"s53",n:53,e:6,y:620,age:50,pl:"makkah",sc:"caravan",
 w:["Tahun ke-10 dan ke-11 kenabian","Years 10 and 11 of prophethood"],
 t:["Orang beriman dari luar Makkah","Believers from outside Makkah"],
 f:["Ketika Makkah menolak, beberapa individu dari luar Makkah mula beriman. Suwaid bin as-Samit, penyair dari Yathrib, mendengar al-Quran dan memujinya. Iyas bin Mu'adh, seorang pemuda Yathrib, beriman ketika rombongannya datang mencari sekutu. Abu Dzar al-Ghifari datang mencari kebenaran dan mengisytiharkan Islamnya di Masjidil Haram. At-Tufail bin Amr ad-Dausi, pembesar kabilah Daus, beriman dan kemudian membawa kaumnya kepada Islam. Dhimad al-Azdi dari Yaman juga beriman.\nMereka seperti bayu harapan yang menandakan bahawa Islam akan tersebar jauh dari Makkah.",
   "While Makkah refused, a few individuals from outside began to believe. Suwayd ibn as-Samit, a poet of Yathrib, heard the Quran and praised it. Iyas ibn Mu'adh, a young man of Yathrib, believed when his group came looking for allies. Abu Dharr al-Ghifari came seeking the truth and declared his Islam at the Sacred Masjid. At-Tufayl ibn 'Amr ad-Dawsi, a chief of Daws, believed and later brought his people to Islam. Dimad al-Azdi of Yemen also believed.\nThey were like breezes of hope, signs that Islam would spread far beyond Makkah."],
 l:[["Kebenaran mencari jalannya sendiri ke hati yang ikhlas.","Truth finds its way to sincere hearts."]],
 s:"Hope Inspiring Breezes from the Madinese, p.82|Golongan beriman bukan dari penduduk Makkah"},

{id:"s54",n:54,e:6,m:1,y:620.5,age:50,pl:"mina",sc:"aqabah",
 w:["Musim haji, tahun ke-11 kenabian (Julai 620)","Hajj season, year 11 of prophethood (July 620)"],
 t:["Enam orang dari Yathrib","Six men of Yathrib accept Islam"],
 f:["Pada suatu malam musim haji, Rasulullah ﷺ bersama Abu Bakar dan Ali melalui 'Aqabah di Mina dan mendengar beberapa lelaki berbual. Mereka ialah enam orang pemuda Khazraj dari Yathrib. Baginda duduk bersama mereka, menerangkan Islam dan membaca al-Quran.\nMereka sering mendengar orang Yahudi di Yathrib berkata bahawa seorang nabi akan diutus tidak lama lagi. Mereka berkata sesama sendiri: “Inilah nabi yang dijanjikan oleh Yahudi itu. Jangan biarkan mereka mendahului kita.” Mereka pun memeluk Islam.\nMereka berharap Allah menyatukan kaum mereka, yang letih dengan peperangan Bu'ath antara Aus dan Khazraj, melalui Baginda. Mereka pulang membawa Islam ke Yathrib, sehingga tiada rumah di sana yang tidak menyebut nama Rasulullah ﷺ.",
   "One night in the Hajj season, the Prophet ﷺ with Abu Bakr and 'Ali passed by 'Aqabah at Mina and heard some men talking. They were six young men of Khazraj from Yathrib. He sat with them, explained Islam and recited the Quran.\nThey had often heard the Jews of Yathrib say that a prophet would soon be sent. They said to each other: “This is the prophet the Jews spoke of. Do not let them reach him before us.” And they accepted Islam.\nThey hoped Allah would unite their people, worn out by the war of Bu'ath between Aws and Khazraj, through him. They went home carrying Islam to Yathrib, until there was no house there that did not speak of the Prophet ﷺ."],
 k:["Pada musim haji, Nabi ﷺ bertemu enam orang pemuda dari bandar Yathrib. Mereka mendengar al-Quran dan terus memeluk Islam. Mereka pulang dan menceritakan tentang Islam kepada keluarga mereka.","During the Hajj season, the Prophet ﷺ met six young men from the town of Yathrib. They listened to the Quran and became Muslims straight away. They went home and told their families about Islam."],
 l:[["Satu pertemuan kecil boleh mengubah sejarah.","One small meeting can change history."],["Allah menyediakan tempat baharu apabila satu pintu tertutup.","Allah prepares a new place when one door closes."]],
 s:"Hope Inspiring Breezes from the Madinese, p.82|Enam jiwa suci dari bumi Yathrib"},

{id:"s55",n:55,e:6,y:620.6,age:50,pl:"makkah",sc:"birth",
 w:["Syawal, sebelum Hijrah","Shawwal, before the Hijrah"],
 t:["Akad nikah dengan Aisyah (r.a.)","Marriage contract with 'A'ishah (r.a.)"],
 f:["Pada bulan Syawal, beberapa tahun sebelum Hijrah, Rasulullah ﷺ berakad nikah dengan Aisyah, puteri sahabat karibnya Abu Bakar as-Siddiq. Menurut Ar-Raheeq yang bersandarkan riwayat al-Bukhari, usia Aisyah ketika itu enam tahun, dan beliau mula tinggal bersama Baginda di Madinah pada bulan Syawal tahun pertama Hijrah ketika berusia sembilan tahun.\nAisyah membesar dalam rumah kenabian dan menjadi antara wanita paling alim dalam sejarah Islam. Beliau meriwayatkan lebih dua ribu hadith, dan para sahabat besar merujuk kepadanya dalam soal agama.",
   "In Shawwal, some years before the Hijrah, the Prophet ﷺ made the marriage contract with 'A'ishah, daughter of his close friend Abu Bakr as-Siddiq. According to Ar-Raheeq, relying on the report in al-Bukhari, she was six at the time, and she began living with him in Madinah in Shawwal of the first year after the Hijrah, at the age of nine.\n'A'ishah grew up in the house of prophethood and became one of the most learned women in the history of Islam. She narrated more than two thousand hadith, and senior companions turned to her on matters of religion."],
 l:[["Ilmu wanita dihargai dan dirujuk dalam Islam.","Women's knowledge is valued and consulted in Islam."]],
 o:["Edisi Melayu menyebut akad ini pada Syawal tahun ke-9 kenabian, manakala edisi Inggeris meletakkannya pada tahun ke-11. Sebahagian pengkaji moden berpendapat usia Aisyah lebih tua.","The Malay edition places the contract in Shawwal of year 9 of prophethood, while the English edition places it in year 11. Some modern researchers hold that 'A'ishah was older."],
 p:["aisyah","abubakar"],s:"Marriage of the Prophet to 'Aishah, p.82|Secebis ulasan mengenai perkahwinan Rasulullah dengan Aisyah"},

{id:"s56",n:56,e:6,m:1,y:621,age:"51",pl:"aqsa",sc:"aqsa",
 w:["Malam hari, pada tahun-tahun akhir sebelum Hijrah","One night, in the last years before the Hijrah"],
 t:["Isra' & Mi'raj: solat lima waktu","Isra' and Mi'raj: the five daily prayers"],
 f:["Pada suatu malam, Rasulullah ﷺ dibawa dengan jasadnya dari Masjidil Haram ke Masjid al-Aqsa di Baitulmaqdis, menunggang Buraq bersama Jibril. Di sana Baginda mengimamkan para nabi dalam solat. Kemudian Baginda dinaikkan ke langit.\nDi langit pertama Baginda bertemu Nabi Adam, di langit kedua Nabi Yahya dan Isa, di langit ketiga Nabi Yusuf, di langit keempat Nabi Idris, di langit kelima Nabi Harun, di langit keenam Nabi Musa dan di langit ketujuh Nabi Ibrahim (a.s.). Mereka semua menyambut Baginda dan mengakui kenabiannya. Baginda dibawa hingga ke Sidratul Muntaha dan al-Bait al-Ma'mur.\nAllah memfardukan lima puluh solat sehari. Atas nasihat Nabi Musa, Baginda kembali memohon keringanan sehingga menjadi lima waktu, dengan pahala lima puluh.\nKeesokan pagi, Quraisy mengejek cerita ini. Abu Bakar berkata: “Jika dia berkata demikian, maka benarlah.” Kerana itu beliau digelar as-Siddiq.",
   "One night the Prophet ﷺ was taken in body from the Sacred Masjid to Masjid al-Aqsa in Jerusalem, riding al-Buraq with Jibril. There he led the prophets in prayer. Then he was raised up through the heavens.\nIn the first heaven he met Adam, in the second Yahya and 'Isa, in the third Yusuf, in the fourth Idris, in the fifth Harun, in the sixth Musa and in the seventh Ibrahim (a.s.). Each welcomed him and affirmed his prophethood. He was taken up to the Lote Tree of the Utmost Boundary and the Frequented House.\nAllah ordained fifty prayers a day. On Musa's advice, he went back and asked for less until they became five, with the reward of fifty.\nNext morning Quraysh mocked the story. Abu Bakr said: “If he said it, then it is true.” That is why he was called as-Siddiq."],
 k:["Pada suatu malam, Allah membawa Nabi ﷺ dari Makkah ke Masjid al-Aqsa, kemudian naik ke langit. Baginda bertemu para nabi. Allah memberi hadiah yang sangat istimewa: solat lima waktu sehari.","One night Allah took the Prophet ﷺ from Makkah to Masjid al-Aqsa, and then up through the heavens. He met the earlier prophets. Allah gave a very special gift: the five daily prayers."],
 l:[["Solat ialah hadiah langsung daripada Allah, bukan melalui wahyu di bumi.","Prayer was a gift given directly in the heavens, not on earth."],["Selepas kesedihan, Allah memuliakan Rasul-Nya.","After sorrow, Allah honoured His Messenger."],["Iman sejati membenarkan berita ghaib daripada Rasul.","True faith affirms what the Messenger tells of the unseen."]],
 ay:[{kid:1,r:"al-Isra' 17:1",ar:"سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِّنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى الَّذِي بَارَكْنَا حَوْلَهُ",m:["Maha Suci Allah yang telah memperjalankan hamba-Nya pada suatu malam dari Masjidil Haram ke Masjid al-Aqsa yang Kami berkati sekelilingnya.","Glory be to Him who took His servant by night from the Sacred Masjid to the Farthest Masjid, whose surroundings We have blessed."]},
     {r:"an-Najm 53:13-14",ar:"وَلَقَدْ رَآهُ نَزْلَةً أُخْرَىٰ ۝ عِندَ سِدْرَةِ الْمُنتَهَىٰ",m:["Dan sesungguhnya dia telah melihatnya pada kali yang lain, di sisi Sidratul Muntaha.","And he certainly saw him in another descent, at the Lote Tree of the Utmost Boundary."]}],
 hd:[{r:"Sahih al-Bukhari 349",m:["Anas (r.a.) meriwayatkan kisah Mi'raj dan bagaimana lima puluh solat menjadi lima waktu.","Anas (r.a.) narrated the Mi'raj and how fifty prayers became five."]}],
 o:["Ar-Raheeq menyenaraikan beberapa pendapat tentang tarikhnya, dan majoriti cenderung kepada 12 hingga 16 bulan sebelum Hijrah. Di Malaysia ia disambut pada 27 Rejab.","Ar-Raheeq lists several opinions on the date, and most favour 12 to 16 months before the Hijrah. In Malaysia it is marked on 27 Rajab."],
 p:["abubakar"],s:"Al-Isra' and Al-Mi'raj, p.89|Isra' dan Mi'raj"},

{id:"s57",n:57,e:6,m:1,y:621.5,age:51,pl:"mina",sc:"aqabah",
 w:["Musim haji, tahun ke-12 kenabian (621)","Hajj season, year 12 of prophethood (621)"],
 t:["Bai'ah Aqabah pertama","The first 'Aqabah pledge"],
 f:["Pada musim haji berikutnya, dua belas lelaki dari Yathrib datang: lima daripada enam orang tahun lalu dan tujuh orang baharu. Sepuluh daripada Khazraj dan dua daripada Aus. Mereka bertemu Rasulullah ﷺ di 'Aqabah, Mina.\nMereka berbai'ah untuk tidak menyekutukan Allah, tidak mencuri, tidak berzina, tidak membunuh anak, tidak membuat fitnah, dan tidak menderhaka dalam perkara yang baik. Sesiapa yang menunaikannya, ganjarannya di sisi Allah.",
   "At the next Hajj season, twelve men from Yathrib came: five of the six from the year before and seven new. Ten were from Khazraj and two from Aws. They met the Prophet ﷺ at 'Aqabah in Mina.\nThey pledged not to associate anything with Allah, not to steal, not to commit adultery, not to kill their children, not to spread slander, and not to disobey him in what is good. Whoever kept the pledge would have his reward with Allah."],
 k:["Tahun berikutnya, dua belas orang dari Yathrib datang dan berjanji kepada Nabi ﷺ: mereka hanya akan menyembah Allah dan sentiasa berbuat baik. Janji ini dipanggil Bai'ah Aqabah.","The next year, twelve people from Yathrib came and promised the Prophet ﷺ that they would worship only Allah and always do good. This promise is called the Pledge of 'Aqabah."],
 l:[["Iman diikuti dengan komitmen akhlak yang jelas.","Faith is followed by a clear commitment to good conduct."]],
 hd:[{r:"Sahih al-Bukhari 18",m:["Ubadah bin as-Samit (r.a.) meriwayatkan isi bai'ah ini.","'Ubadah ibn as-Samit (r.a.) narrated the terms of this pledge."]}],
 s:"The First 'Aqabah Pledge, p.93|Bai'ah al-Aqabah pertama"},

{id:"s58",n:58,e:6,y:621.6,age:51,pl:"madinah",sc:"madinah",
 w:["621 hingga 622","621 to 622"],
 t:["Mus'ab bin Umair, duta Islam ke Madinah","Mus'ab ibn 'Umair, the envoy to Madinah"],
 f:["Bersama rombongan Aqabah pertama, Rasulullah ﷺ mengutus Mus'ab bin Umair, seorang pemuda Makkah yang dahulunya hidup mewah, untuk mengajar al-Quran dan Islam di Yathrib. Beliau tinggal di rumah As'ad bin Zurarah dan digelar ‘al-Muqri'’, guru al-Quran.\nDengan kelembutan dan kebijaksanaannya, Usaid bin Hudair dan Sa'd bin Mu'adh, dua ketua Bani Abdul Asyhal, memeluk Islam. Sa'd lalu berkata kepada kaumnya bahawa dia tidak akan bercakap dengan mereka sehingga mereka beriman. Pada petang itu juga, seluruh Bani Abdul Asyhal memeluk Islam.\nMenjelang musim haji berikutnya, Islam sudah ada di hampir setiap rumah Ansar.",
   "With the first 'Aqabah group, the Prophet ﷺ sent Mus'ab ibn 'Umair, a young Makkan who had once lived in luxury, to teach the Quran and Islam in Yathrib. He stayed with As'ad ibn Zurarah and was called ‘al-Muqri'’, the Quran teacher.\nThrough his gentleness and wisdom, Usayd ibn Hudayr and Sa'd ibn Mu'adh, the two chiefs of Banu 'Abd al-Ashhal, accepted Islam. Sa'd then told his people he would not speak to them until they believed. By that evening the whole of Banu 'Abd al-Ashhal had accepted Islam.\nBy the next Hajj season, Islam had reached almost every home of the Ansar."],
 l:[["Seorang guru yang ikhlas dan lembut boleh mengubah sebuah bandar.","One sincere and gentle teacher can change a whole town."]],
 p:["musab","saad"],s:"The Muslim Envoy in Madinah, p.93|Duta Islam ke Madinah; Kejayaan yang cemerlang"},

{id:"s59",n:59,e:6,m:1,y:622.45,age:52,pl:"mina",sc:"aqabah",
 w:["Musim haji, tahun ke-13 kenabian (Jun 622)","Hajj season, year 13 of prophethood (June 622)"],
 t:["Bai'ah Aqabah kedua","The second 'Aqabah pledge"],
 f:["Pada musim haji tahun ketiga belas kenabian, lebih tujuh puluh orang Islam dari Yathrib datang bersama jemaah haji kaum mereka. Pada malam hari tasyriq, selepas sepertiga malam, tujuh puluh tiga lelaki dan dua wanita menyelinap ke 'Aqabah untuk bertemu Rasulullah ﷺ secara rahsia. Bapa saudara Baginda, al-'Abbas, yang belum memeluk Islam, turut hadir dan berucap dahulu untuk memastikan kesungguhan mereka.\nMereka berbai'ah untuk mendengar dan taat dalam keadaan rajin dan malas, berinfak ketika senang dan susah, menyuruh kebaikan dan mencegah kemungkaran, dan melindungi Baginda seperti mereka melindungi diri, isteri dan anak mereka. Ganjarannya ialah syurga.\nBaginda melantik dua belas orang naqib sebagai ketua: sembilan daripada Khazraj dan tiga daripada Aus. Bai'ah ini membuka jalan kepada Hijrah.",
   "In the Hajj season of the thirteenth year of prophethood, more than seventy Muslims from Yathrib came among their people's pilgrims. On one of the nights of tashriq, after a third of the night had passed, seventy-three men and two women slipped away to 'Aqabah to meet the Prophet ﷺ in secret. His uncle al-'Abbas, not yet a Muslim, was there and spoke first to make sure they were serious.\nThey pledged to listen and obey in energy and in weariness, to spend in ease and hardship, to enjoin good and forbid evil, and to protect him as they protected themselves, their wives and their children. The reward was Paradise.\nHe appointed twelve leaders (naqib): nine from Khazraj and three from Aws. This pledge opened the way to the Hijrah."],
 k:["Tahun berikutnya, lebih tujuh puluh orang dari Yathrib datang. Mereka berjanji akan melindungi Nabi ﷺ jika Baginda datang ke bandar mereka. Kini orang Islam ada tempat yang selamat!","The following year, more than seventy people from Yathrib came. They promised to protect the Prophet ﷺ if he came to their town. Now the Muslims had a safe place!"],
 l:[["Janji setia yang jelas ialah asas sebuah masyarakat.","A clear pledge is the base of a community."],["Wanita turut serta dalam peristiwa penting ini.","Women took part in this historic pledge."]],
 s:"The Second 'Aqabah Pledge, p.95|Perjanjian al-'Aqabah kedua"},

{id:"s60",n:60,e:6,y:622.5,age:52,pl:"madinah",sc:"caravan",
 w:["622, selepas Aqabah kedua","622, after the second 'Aqabah pledge"],
 t:["Kumpulan pertama berhijrah ke Madinah","The first groups migrate to Madinah"],
 f:["Selepas Bai'ah Aqabah kedua, Rasulullah ﷺ mengizinkan para sahabat berhijrah ke Yathrib. Mereka keluar secara senyap, berkumpulan kecil, meninggalkan rumah dan harta.\nAbu Salamah dan keluarganya sudah berhijrah lebih awal, tetapi isteri dan anaknya ditahan berasingan oleh keluarga mereka selama setahun. Suhaib ar-Rumi menyerahkan semua hartanya kepada Quraisy supaya dibenarkan pergi, lalu Rasulullah ﷺ bersabda: “Untunglah jual beli Suhaib.” Ada juga yang ditipu dan dibawa pulang ke Makkah.\nDalam masa dua bulan lebih, hampir semua orang Islam telah berhijrah, kecuali Rasulullah ﷺ, Abu Bakar, Ali dan mereka yang ditahan secara paksa.",
   "After the second 'Aqabah pledge, the Prophet ﷺ gave the companions leave to migrate to Yathrib. They slipped out quietly in small groups, leaving their homes and wealth behind.\nAbu Salamah and his family had gone earlier, but his wife and child were held apart by their relatives for a year. Suhayb ar-Rumi handed all his wealth to Quraysh so they would let him go, and the Prophet ﷺ said: “Suhayb's trade has profited.” Some were tricked and taken back to Makkah.\nWithin a little over two months, almost all the Muslims had migrated, except the Prophet ﷺ, Abu Bakr, 'Ali and those held back by force."],
 l:[["Hijrah menuntut pengorbanan harta, keluarga dan tanah air.","Hijrah demanded sacrifice of wealth, family and homeland."]],
 s:"The Vanguard of Migration, p.99|Kumpulan sulung berhijrah"},

{id:"s61",n:61,e:6,y:622.69,ah:1,age:52,pl:"makkah",sc:"nadwah",
 w:["Khamis, 26 Safar, tahun ke-14 kenabian (12 September 622)","Thursday, 26 Safar, year 14 of prophethood (12 September 622)"],
 t:["Sidang Dar an-Nadwah: rancangan membunuh","Quraysh's council plans to kill him"],
 f:["Quraisy bimbang melihat orang Islam berhimpun di Yathrib. Pada pagi Khamis, 26 Safar, pembesar mereka bersidang di Dar an-Nadwah. Diriwayatkan bahawa Iblis turut hadir dalam rupa seorang tua dari Najd.\nCadangan untuk memenjara dan mengusir Rasulullah ﷺ ditolak. Akhirnya Abu Jahal mencadangkan agar setiap kabilah memilih seorang pemuda yang gagah. Mereka akan menyerang Baginda serentak supaya darahnya tertumpah ke atas semua kabilah, dan Bani Hasyim tidak mampu menuntut bela. Cadangan ini dipersetujui.\nAllah mendedahkan rancangan mereka kepada Rasul-Nya.",
   "Quraysh grew alarmed to see the Muslims gathering in Yathrib. On Thursday morning, 26 Safar, their leaders met at Dar an-Nadwah. It is reported that Iblis was there in the shape of an old man from Najd.\nProposals to imprison or exile the Prophet ﷺ were rejected. In the end Abu Jahl proposed that each clan choose a strong young man. They would strike him together, so his blood would be shared among all the clans and Banu Hashim could not seek revenge. The plan was agreed.\nAllah revealed their plot to His Messenger."],
 l:[["Tipu daya manusia tidak dapat mengatasi rancangan Allah.","Human scheming cannot overcome Allah's plan."]],
 ay:[{r:"al-Anfal 8:30",ar:"وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ ۚ وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ ۖ وَاللَّهُ خَيْرُ الْمَاكِرِينَ",m:["Dan ingatlah ketika orang kafir merancang tipu daya terhadapmu untuk menahanmu, membunuhmu atau mengusirmu. Mereka merancang, dan Allah juga merancang, dan Allah sebaik-baik perancang.","And when the disbelievers plotted against you to restrain you, kill you or drive you out. They plan, and Allah plans, and Allah is the best of planners."]}],
 p:["abujahal"],s:"In An-Nadwah House, p.101|Sidang Darul al-Nadwah"},

{id:"s62",n:62,e:7,m:1,y:622.7,ah:1,age:52,pl:"makkah",sc:"house",
 w:["Malam 27 Safar, tahun ke-14 kenabian (12/13 September 622)","Night of 27 Safar, year 14 of prophethood (12/13 September 622)"],
 t:["Rumah dikepung: Ali di tempat tidur","The house surrounded: 'Ali in his bed"],
 f:["Jibril memberitahu Rasulullah ﷺ tentang rancangan Quraisy dan izin untuk berhijrah. Pada tengah hari yang panas, Baginda datang ke rumah Abu Bakar dengan menutup wajah untuk mengatur perjalanan.\nPada malamnya, sebelas orang pembesar Quraisy mengepung rumah Baginda, menunggu Baginda keluar untuk subuh. Baginda menyuruh Ali tidur di tempat tidurnya berselimutkan kain hijau Hadrami miliknya, dan memulangkan barang-barang amanah orang Makkah keesokan harinya. Walaupun mereka memusuhi Baginda, mereka masih menyimpan harta di tangannya.\nRasulullah ﷺ keluar melalui mereka sambil menaburkan segenggam pasir dan membaca ayat Surah Yasin. Allah menutup pandangan mereka, dan Baginda pergi ke rumah Abu Bakar. Pagi itu mereka mendapati Ali di tempat tidur.",
   "Jibril told the Prophet ﷺ of the Quraysh plot and of the permission to migrate. At the heat of midday he came to Abu Bakr's house with his face covered to arrange the journey.\nThat night, eleven Quraysh chiefs surrounded his house, waiting for him to come out at dawn. He told 'Ali to sleep in his bed under his green Hadrami cloak, and to return to the people of Makkah the things they had left in his trust. Even while they were his enemies, they still kept their valuables with him.\nThe Prophet ﷺ walked out past them, scattering a handful of dust and reciting from Surah Yasin. Allah covered their sight, and he went to Abu Bakr's house. In the morning they found 'Ali in the bed."],
 k:["Pada malam Hijrah, orang jahat mengepung rumah Nabi ﷺ. Ali yang berani tidur di tempat tidur Nabi ﷺ. Allah melindungi Nabi ﷺ dan Baginda keluar tanpa dilihat oleh mereka.","On the night of the Hijrah, bad men surrounded the Prophet's ﷺ house. Brave 'Ali slept in the Prophet's ﷺ bed. Allah protected the Prophet ﷺ and he walked out without them seeing him."],
 l:[["Amanah tetap dipulangkan walaupun kepada musuh.","Trusts are returned, even to enemies."],["Keberanian pemuda seperti Ali menjadi contoh.","The courage of a young man like 'Ali is an example."]],
 ay:[{r:"Yasin 36:9",ar:"وَجَعَلْنَا مِن بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَاهُمْ فَهُمْ لَا يُبْصِرُونَ",m:["Dan Kami jadikan di hadapan mereka dinding dan di belakang mereka dinding, lalu Kami tutup pandangan mereka sehingga mereka tidak dapat melihat.","And We have put a barrier before them and a barrier behind them, and covered them so they cannot see."]}],
 p:["ali","abubakar","abujahal"],s:"Migration of the Prophet, p.103|Rasulullah meninggalkan rumahnya"},

{id:"s63",n:63,e:7,m:1,y:622.705,ah:1,age:52,pl:"thaur",sc:"thaur",
 w:["27 Safar hingga 1 Rabiulawal (Jumaat, Sabtu, Ahad)","27 Safar to 1 Rabi' al-Awwal (Friday, Saturday, Sunday)"],
 t:["Tiga malam di Gua Thaur","Three nights in the Cave of Thaur"],
 f:["Rasulullah ﷺ dan Abu Bakar keluar sebelum fajar, menuju ke selatan ke Gua Thaur, arah yang bertentangan dengan Yathrib, untuk mengelirukan Quraisy. Mereka bersembunyi di situ selama tiga malam. Abdullah bin Abi Bakar datang setiap malam membawa berita dari Makkah. Amir bin Fuhairah menggembala kambing di situ untuk memberi susu dan memadam jejak. Asma' binti Abi Bakar mengikat bekalan dengan tali pinggangnya yang dikoyak dua, lalu digelar Dzatun Nitaqain.\nQuraisy menawarkan seratus ekor unta untuk setiap seorang. Para pemburu sampai ke mulut gua. Abu Bakar berbisik: “Jika salah seorang daripada mereka melihat ke bawah kakinya, pasti dia nampak kita.” Baginda menjawab: “Apa sangkaanmu terhadap dua orang, yang ketiganya ialah Allah?” Allah pun menurunkan ketenangan.",
   "The Prophet ﷺ and Abu Bakr left before dawn, heading south to the Cave of Thaur, away from Yathrib, to mislead Quraysh. They hid there for three nights. 'Abdullah ibn Abi Bakr came each night with news from Makkah. 'Amir ibn Fuhayrah grazed sheep nearby to give them milk and cover their tracks. Asma' bint Abi Bakr tied the provisions with her belt torn in two, and was called ‘the one with two belts’.\nQuraysh offered a hundred camels for each of them. The searchers reached the mouth of the cave. Abu Bakr whispered: “If one of them looked down at his feet, he would see us.” He answered: “What do you think of two, when Allah is the third?” And Allah sent down calm."],
 k:["Nabi ﷺ dan sahabatnya Abu Bakar bersembunyi di Gua Thaur selama tiga malam. Orang jahat sampai ke pintu gua! Abu Bakar risau, tetapi Nabi ﷺ berkata: “Jangan bersedih, Allah bersama kita.”","The Prophet ﷺ and his friend Abu Bakr hid in the Cave of Thaur for three nights. The bad men came right up to the cave! Abu Bakr was worried, but the Prophet ﷺ said: “Do not be sad, Allah is with us.”"],
 l:[["Usaha dan perancangan rapi berjalan seiring dengan tawakal.","Careful planning goes hand in hand with trust in Allah."],["Seluruh keluarga Abu Bakar berkhidmat untuk Hijrah.","Abu Bakr's whole family served the Hijrah."]],
 ay:[{kid:1,r:"at-Taubah 9:40",ar:"إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا",m:["Ketika dia berkata kepada sahabatnya: Jangan bersedih, sesungguhnya Allah bersama kita.","When he said to his companion: Do not grieve, indeed Allah is with us."]}],
 hd:[{r:"Sahih al-Bukhari 3653",m:["Abu Bakar meriwayatkan: “Apa sangkaanmu, wahai Abu Bakar, terhadap dua orang yang ketiganya ialah Allah?”","Abu Bakr narrated: “What do you think, Abu Bakr, of two when Allah is the third?”"]}],
 o:["Kisah sarang labah-labah di pintu gua datang daripada riwayat lain (Musnad Ahmad) dan tidak disebut dalam Ar-Raheeq.","The story of the spider's web at the cave comes from another report (Musnad Ahmad) and is not mentioned in Ar-Raheeq."],
 p:["abubakar","asma"],s:"Migration of the Prophet, p.103|Dari rumah ke gua"},

{id:"s64",n:64,e:7,y:622.71,ah:1,age:52,pl:"coast",sc:"hoof",
 w:["Isnin, 1 Rabiulawal dan seterusnya","Monday, 1 Rabi' al-Awwal onwards"],
 t:["Suraqah bin Malik mengejar","Suraqah gives chase"],
 f:["Pada malam Isnin, 1 Rabiulawal, mereka bertolak dari gua bersama penunjuk jalan Abdullah bin Uraiqit, seorang yang belum beriman tetapi dipercayai, dan Amir bin Fuhairah. Mereka mengambil jalan pantai yang jarang dilalui.\nSuraqah bin Malik dari Bani Mudlij mendengar khabar tentang mereka dan mengejar dengan kudanya demi hadiah seratus ekor unta. Apabila hampir, kudanya tersungkur. Dia mencuba lagi, dan kaki kudanya terbenam ke dalam pasir hingga ke lutut. Dia sedar Baginda dilindungi, lalu meminta jaminan keselamatan secara bertulis dan berjanji untuk mengalihkan para pengejar. Suraqah memeluk Islam beberapa tahun kemudian.",
   "On the night of Monday, 1 Rabi' al-Awwal, they left the cave with their guide 'Abdullah ibn Urayqit, who was not yet a believer but was trusted, and 'Amir ibn Fuhayrah. They took the little-used coastal road.\nSuraqah ibn Malik of Banu Mudlij heard of them and rode after them for the reward of a hundred camels. As he drew close, his horse stumbled. He tried again, and his horse's legs sank into the sand up to the knees. He realised the Prophet was protected, asked for a written promise of safety, and promised to turn other pursuers away. Suraqah accepted Islam some years later."],
 l:[["Orang yang mengejar untuk mencelakakan boleh berubah menjadi pelindung.","One who chased to harm can turn into a protector."]],
 hd:[{r:"Sahih al-Bukhari 3906",m:["Suraqah sendiri menceritakan bagaimana kudanya terbenam ketika mengejar Rasulullah ﷺ.","Suraqah himself told how his horse sank as he chased the Prophet ﷺ."]}],
 p:["suraqah","abubakar"],s:"Migration of the Prophet, p.103|Dalam perjalanan ke Madinah"},

{id:"s65",n:65,e:7,y:622.715,ah:1,age:52,pl:"qudaid",sc:"tent2",
 w:["Rabiulawal, dalam perjalanan","Rabi' al-Awwal, on the road"],
 t:["Khemah Ummu Ma'bad","The tent of Umm Ma'bad"],
 f:["Di Qudaid, para musafir singgah di khemah Ummu Ma'bad, seorang wanita Badwi yang pemurah. Ketika itu musim kemarau dan beliau tiada makanan. Di sudut khemah ada seekor kambing yang terlalu kurus untuk mengikut kawanan, dan tidak bersusu.\nRasulullah ﷺ meminta izin, mengusap susunya sambil menyebut nama Allah, dan kambing itu mengeluarkan susu yang banyak. Semua minum hingga puas, dan bekas itu diisi semula untuk tuan rumah.\nApabila suaminya pulang dan hairan, Ummu Ma'bad menggambarkan tetamu itu: wajahnya berseri, akhlaknya mulia, matanya hitam dan bulu matanya panjang, suaranya lembut, tenang ketika diam dan indah ketika berbicara. Suaminya berkata: “Demi Allah, inilah lelaki Quraisy itu.”",
   "At Qudaid the travellers stopped at the tent of Umm Ma'bad, a generous Bedouin woman. It was a time of drought and she had no food. In a corner was a sheep too thin to go with the flock, and with no milk.\nThe Prophet ﷺ asked permission, stroked its udder saying the name of Allah, and the sheep gave plenty of milk. Everyone drank their fill, and the vessel was filled again for the hostess.\nWhen her husband came back amazed, Umm Ma'bad described the guest: a bright face, a noble manner, dark eyes with long lashes, a gentle voice, calm in silence and beautiful in speech. Her husband said: “By Allah, that is the man of Quraysh.”"],
 l:[["Keberkatan Rasulullah ﷺ dirasai oleh orang biasa yang ditemui di jalan.","Ordinary people met on the road felt the Prophet's ﷺ blessing."]],
 p:["ummmabad"],s:"Migration of the Prophet, p.103|Dalam perjalanan ke Madinah"},

{id:"s66",n:66,e:7,m:1,y:622.73,ah:1,age:"52",pl:"quba",sc:"quba",
 w:["Isnin, 8 Rabiulawal, tahun ke-14 kenabian (23 September 622)","Monday, 8 Rabi' al-Awwal, year 14 of prophethood (23 September 622)"],
 t:["Tiba di Quba': masjid pertama","Arrival at Quba': the first masjid"],
 f:["Setiap pagi, orang Islam di Madinah keluar ke Harrah menunggu kedatangan Rasulullah ﷺ hingga matahari terik. Pada hari Isnin, 8 Rabiulawal, seorang Yahudi di atas benteng melihat mereka dan menjerit: “Wahai orang Arab, inilah orang yang kamu tunggu!” Orang ramai bergegas dengan senjata untuk menyambut.\nBaginda singgah di Quba' di rumah Kulthum bin al-Hidm dan tinggal di sana beberapa hari. Di sinilah Baginda mengasaskan Masjid Quba', masjid pertama yang dibina atas dasar takwa. Ali bin Abi Talib menyusul ke Quba' selepas memulangkan barang amanah di Makkah.",
   "Every morning the Muslims of Madinah went out to the lava plain to wait for the Prophet ﷺ until the sun grew too hot. On Monday, 8 Rabi' al-Awwal, a Jewish man on a fort saw them and shouted: “O Arabs, here is the one you have been waiting for!” The people rushed out with their weapons to welcome him.\nHe stopped at Quba' at the house of Kulthum ibn al-Hidm and stayed there a few days. Here he founded Masjid Quba', the first masjid built on piety. 'Ali ibn Abi Talib caught up at Quba' after returning the trusts in Makkah."],
 k:["Selepas perjalanan yang panjang, Nabi ﷺ tiba di Quba', dekat Madinah. Orang ramai menyambut Baginda dengan gembira. Di situ Baginda membina masjid pertama: Masjid Quba'.","After a long journey, the Prophet ﷺ arrived at Quba', near Madinah. People welcomed him joyfully. There he built the very first masjid: Masjid Quba'."],
 l:[["Masjid ialah binaan pertama dalam masyarakat Islam.","A masjid is the first building of a Muslim community."]],
 ay:[{r:"at-Taubah 9:108",ar:"لَّمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ",m:["Sesungguhnya masjid yang diasaskan atas dasar takwa sejak hari pertama lebih layak engkau berdiri (bersolat) di dalamnya.","A masjid founded on piety from the first day is more worthy for you to stand in."]}],
 o:["Ar-Raheeq menyebut Baginda tinggal di Quba' empat hari (Isnin hingga Khamis). Riwayat al-Bukhari menyebut lebih sepuluh malam.","Ar-Raheeq says he stayed at Quba' four days (Monday to Thursday). A report in al-Bukhari says more than ten nights."],
 p:["ali"],s:"Migration of the Prophet, p.103|Persinggahan di Quba'"},

{id:"s67",n:67,e:7,y:622.74,ah:1,age:52,pl:"madinah",sc:"madinah",
 w:["Jumaat, 12 Rabiulawal 1 H (27 September 622)","Friday, 12 Rabi' al-Awwal 1 AH (27 September 622)"],
 t:["Solat Jumaat pertama","The first Jumu'ah"],
 f:["Pada hari Jumaat, Rasulullah ﷺ bertolak dari Quba' menuju ke Madinah. Apabila waktu solat tiba, Baginda berada di perkampungan Bani Salim bin Auf, di sebuah lembah. Di situ Baginda mendirikan solat Jumaat bersama kira-kira seratus orang lelaki dan menyampaikan khutbah.\nInilah solat Jumaat pertama yang diimamkan oleh Rasulullah ﷺ. Di tempat itu kini berdiri Masjid al-Jumu'ah.",
   "On Friday the Prophet ﷺ set out from Quba' toward Madinah. When the time of prayer came, he was among Banu Salim ibn 'Awf, in a valley. There he led the Friday prayer with about a hundred men and gave a sermon.\nThis was the first Friday prayer the Prophet ﷺ led. Masjid al-Jumu'ah stands on that spot today."],
 l:[["Solat Jumaat menghimpunkan masyarakat setiap minggu.","The Friday prayer gathers the community every week."]],
 ay:[{r:"al-Jumu'ah 62:9",ar:"يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِن يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ",m:["Wahai orang beriman, apabila diseru untuk solat pada hari Jumaat, maka bersegeralah kepada mengingati Allah.","O you who believe, when the call is made for prayer on Friday, hasten to the remembrance of Allah."]}],
 s:"Migration of the Prophet, p.103|Memasuki al-Madinah"},

{id:"s68",n:68,e:7,m:1,y:622.745,ah:1,age:52,pl:"madinah",sc:"madinah",
 w:["Rabiulawal 1 H (September 622)","Rabi' al-Awwal 1 AH (September 622)"],
 t:["Memasuki Madinah: unta berhenti","Entering Madinah: the camel kneels"],
 f:["Selepas solat Jumaat, Rasulullah ﷺ memasuki Yathrib. Penduduknya keluar beramai-ramai dengan gembira, memuji Allah. Sejak hari itu, Yathrib dikenali sebagai Madinat ar-Rasul, kota Rasul, atau ringkasnya al-Madinah.\nSetiap keluarga Ansar memegang tali unta Baginda dan merayu agar Baginda tinggal bersama mereka. Baginda berkata: “Biarkan dia, dia diperintah.” Unta itu terus berjalan sehingga berlutut di tanah milik dua anak yatim Bani an-Najjar, keluarga sebelah nenda Baginda. Di situlah kemudian dibina Masjid an-Nabawi.\nAbu Ayyub al-Ansari segera membawa barang Baginda ke rumahnya, dan Baginda tinggal di situ sehingga masjid dan bilik-biliknya siap.",
   "After the Friday prayer, the Prophet ﷺ entered Yathrib. Its people poured out joyfully, praising Allah. From that day Yathrib was called Madinat ar-Rasul, the City of the Messenger, or simply al-Madinah.\nEvery family of the Ansar took hold of his camel's rein and begged him to stay with them. He said: “Let her go, she is under command.” The camel walked on until it knelt on land belonging to two orphans of Banu an-Najjar, his grandmother's family. That is where the Prophet's Masjid was later built.\nAbu Ayyub al-Ansari quickly took his baggage to his house, and he stayed there until the masjid and its rooms were finished."],
 k:["Nabi ﷺ tiba di Madinah dan semua orang bergembira! Setiap keluarga mahu Nabi ﷺ tinggal bersama mereka. Nabi ﷺ membiarkan untanya memilih, dan unta itu berhenti dekat rumah Abu Ayyub.","The Prophet ﷺ arrived in Madinah and everyone was overjoyed! Every family wanted him to stay with them. He let his camel choose, and it stopped near the house of Abu Ayyub."],
 l:[["Keputusan yang adil mengelakkan rasa kecewa dalam masyarakat.","A fair decision avoids hurt feelings in a community."],["Sambutan Ansar ialah contoh memuliakan tetamu.","The Ansar's welcome is a model of honouring a guest."]],
 p:["abuayyub"],s:"Migration of the Prophet, p.103|Memasuki al-Madinah"},

{id:"s69",n:69,e:8,y:622.8,ah:1,age:53,pl:"madinah",sc:"madinah",
 w:["Tahun 1 Hijrah","The year 1 AH"],
 t:["Keadaan Madinah ketika Hijrah","Madinah at the time of the Hijrah"],
 f:["Madinah ketika itu terdiri daripada tiga kumpulan. Pertama, orang Islam: Muhajirin yang datang dengan tangan kosong, dan Ansar dari Aus dan Khazraj. Kedua, orang Arab yang masih musyrik, dan dalam kalangan mereka lahir golongan munafik yang diketuai Abdullah bin Ubai. Ketiga, kabilah Yahudi: Bani Qainuqa', Bani an-Nadhir dan Bani Quraizah, yang menguasai banyak ekonomi bandar.\nAus dan Khazraj baru sahaja letih daripada peperangan Bu'ath yang panjang. Muhajirin pula menghadapi cuaca baharu dan demam Madinah. Rasulullah ﷺ perlu menyatukan semua ini menjadi sebuah masyarakat baharu.",
   "Madinah then held three groups. First, the Muslims: the Muhajirin who arrived empty-handed, and the Ansar of Aws and Khazraj. Second, Arabs still worshipping idols, among whom grew the hypocrites led by 'Abdullah ibn Ubayy. Third, the Jewish tribes: Banu Qaynuqa', Banu an-Nadir and Banu Qurayzah, who controlled much of the town's economy.\nAws and Khazraj were exhausted from the long war of Bu'ath. The Muhajirin faced a new climate and the fever of Madinah. The Prophet ﷺ had to unite all of this into a new society."],
 l:[["Memahami keadaan masyarakat ialah langkah pertama membina.","Understanding a society is the first step in building it."]],
 ay:[{r:"Ali 'Imran 3:103",ar:"وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا",m:["Dan berpeganglah kamu semua kepada tali Allah, dan janganlah kamu berpecah-belah.","And hold firmly to the rope of Allah all together, and do not be divided."]}],
 s:"The Status Quo in Madinah at the Time of Emigration, p.114|Keadaan semasa di Madinah ketika hijrah"},

{id:"s70",n:70,e:8,m:1,y:622.8,ah:1,age:53,pl:"madinah",sc:"masjid",
 w:["Tahun 1 Hijrah","The year 1 AH"],
 t:["Pembinaan Masjid an-Nabawi","Building the Prophet's Masjid"],
 f:["Langkah pertama Rasulullah ﷺ di Madinah ialah membina masjid di tempat untanya berlutut. Baginda membeli tanah itu daripada dua anak yatim, walaupun mereka mahu memberikannya secara percuma.\nBaginda sendiri mengangkat batu bata bersama para sahabat sambil bersyair: “Tiada kehidupan melainkan kehidupan akhirat, maka ampunilah Ansar dan Muhajirin.” Masjid itu dibina daripada bata tanah, tiangnya batang kurma dan bumbungnya pelepah kurma. Kiblatnya ketika itu menghadap Baitulmaqdis. Di sebelahnya dibina bilik-bilik untuk isteri-isteri Baginda.\nMasjid ini bukan sahaja tempat solat. Ia sekolah, tempat bermesyuarat, pusat pemerintahan, dan tempat tinggal golongan fakir Muhajirin yang dikenali sebagai Ahl as-Suffah.",
   "The Prophet's ﷺ first step in Madinah was to build a masjid where his camel had knelt. He bought the land from the two orphans, though they wanted to give it for free.\nHe carried bricks himself alongside his companions, chanting: “There is no life but the life of the Hereafter, so forgive the Ansar and the Muhajirin.” The masjid was made of mud brick, with palm-trunk pillars and a roof of palm fronds. Its qiblah then faced Jerusalem. Beside it, rooms were built for his wives.\nThe masjid was more than a place of prayer. It was a school, a meeting hall, the seat of government, and a home for the poor Muhajirin known as the People of the Suffah."],
 k:["Di Madinah, Nabi ﷺ dan para sahabat membina masjid bersama-sama. Nabi ﷺ sendiri mengangkat batu bata! Masjid itu dibuat daripada tanah liat dan batang pokok kurma.","In Madinah, the Prophet ﷺ and his companions built a masjid together. The Prophet ﷺ carried bricks himself! It was made of mud bricks and palm tree trunks."],
 l:[["Pemimpin bekerja bersama rakyatnya.","A leader works alongside his people."],["Masjid ialah pusat kehidupan masyarakat, bukan hanya tempat solat.","A masjid is the centre of community life, not only a place of prayer."]],
 hd:[{r:"Sahih al-Bukhari 428",m:["Anas (r.a.) menceritakan pembelian tanah Bani an-Najjar dan pembinaan masjid.","Anas (r.a.) related the purchase of the land of Banu an-Najjar and the building of the masjid."]}],
 s:"A New Society Being Built, p.114|Pembinaan Masjid an-Nabawi"},

{id:"s71",n:71,e:8,m:1,y:622.85,ah:1,age:53,pl:"madinah",sc:"family",
 w:["Tahun 1 Hijrah","The year 1 AH"],
 t:["Mempersaudarakan Muhajirin & Ansar","The brotherhood of the Muhajirin and the Ansar"],
 f:["Rasulullah ﷺ menghimpunkan sembilan puluh orang, separuh Muhajirin dan separuh Ansar, di rumah Anas bin Malik, lalu mempersaudarakan mereka berpasangan. Persaudaraan ini begitu kuat sehingga pada awalnya mereka saling mewarisi, sebelum hukum itu dimansuhkan selepas Badar.\nSa'd bin ar-Rabi' dari Ansar menawarkan separuh hartanya kepada saudaranya Abdul Rahman bin Auf. Abdul Rahman mendoakan keberkatan untuknya dan berkata: “Tunjukkan kepadaku jalan ke pasar.” Beliau berniaga hingga berjaya dengan usahanya sendiri.\nPersaudaraan ini menghapuskan perbezaan kabilah, warna dan keturunan, dan menggantikannya dengan ikatan iman.",
   "The Prophet ﷺ gathered ninety men, half Muhajirin and half Ansar, in the house of Anas ibn Malik, and made them brothers in pairs. The bond was so strong that at first they even inherited from each other, until that ruling was lifted after Badr.\nSa'd ibn ar-Rabi' of the Ansar offered half of everything he owned to his brother 'Abdur-Rahman ibn 'Awf. 'Abdur-Rahman prayed for blessing on him and said: “Show me the way to the market.” He traded until he succeeded by his own effort.\nThis brotherhood erased differences of tribe, colour and lineage, and replaced them with the bond of faith."],
 k:["Orang Makkah yang berhijrah (Muhajirin) datang tanpa harta. Nabi ﷺ menjadikan setiap seorang daripada mereka bersaudara dengan seorang penduduk Madinah (Ansar). Mereka saling berkongsi dan menolong.","The Muslims who came from Makkah (the Muhajirin) arrived with nothing. The Prophet ﷺ made each of them a brother to someone from Madinah (the Ansar). They shared and helped each other."],
 l:[["Memberi dengan murah hati, dan menerima dengan maruah.","Give generously, and receive with dignity."],["Ikatan iman lebih kuat daripada ikatan darah.","The bond of faith is stronger than the bond of blood."]],
 ay:[{r:"al-Hasyr 59:9",ar:"وَيُؤْثِرُونَ عَلَىٰ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ",m:["Dan mereka mengutamakan (orang lain) atas diri mereka sendiri, walaupun mereka dalam kesusahan.","And they give preference to others over themselves, even though they are in need."]}],
 hd:[{r:"Sahih al-Bukhari 3780",m:["Kisah Sa'd bin ar-Rabi' menawarkan hartanya dan Abdul Rahman bin Auf meminta ditunjukkan jalan ke pasar.","The story of Sa'd ibn ar-Rabi' offering his wealth and 'Abdur-Rahman ibn 'Awf asking for the way to the market."]}],
 s:"A New Society Being Built, p.114|Mempersaudarakan kaum muslimin"},

{id:"s72",n:72,e:8,m:1,y:622.9,ah:1,age:53,pl:"madinah",sc:"charter",
 w:["Tahun 1 Hijrah","The year 1 AH"],
 t:["Piagam Madinah & perjanjian dengan Yahudi","The Madinah Charter and the pact with the Jews"],
 f:["Rasulullah ﷺ menulis satu piagam yang mengatur hubungan semua penduduk Madinah. Orang beriman ialah satu umat. Mereka saling membantu, membayar diat dan menebus tawanan bersama, dan tidak boleh melindungi musuh atau penjenayah. Sebarang perselisihan dirujuk kepada Allah dan Rasul-Nya.\nBaginda juga membuat perjanjian dengan kabilah Yahudi. Mereka bebas mengamalkan agama mereka, menanggung belanja sendiri, dan wajib bersama-sama mempertahankan Madinah daripada serangan. Kedua-dua pihak saling menasihati dan tidak mengkhianati.\nDengan piagam ini, Madinah menjadi sebuah negara dengan undang-undang bertulis, dan Rasulullah ﷺ menjadi ketuanya.",
   "The Prophet ﷺ wrote a charter setting out the relations of everyone in Madinah. The believers were one community. They helped each other, paid blood money and ransomed captives together, and could not shelter enemies or wrongdoers. Any dispute was referred to Allah and His Messenger.\nHe also made a pact with the Jewish tribes. They were free to practise their religion, bore their own costs, and were bound to defend Madinah together against attack. Both sides would advise each other and not betray.\nWith this charter, Madinah became a state with written law, and the Prophet ﷺ was its head."],
 k:["Nabi ﷺ menulis peraturan supaya semua penduduk Madinah, Islam dan bukan Islam, hidup dengan aman dan adil. Semua orang berjanji untuk menjaga Madinah bersama-sama.","The Prophet ﷺ wrote down rules so that everyone in Madinah, Muslim and non-Muslim, could live in peace and fairness. Everyone promised to protect Madinah together."],
 l:[["Islam membina masyarakat berasaskan undang-undang dan keadilan.","Islam builds society on law and justice."],["Hak orang bukan Islam dipelihara dalam perjanjian.","The rights of non-Muslims were protected by agreement."]],
 s:"A Charter of Islamic Alliance; A Cooperation and Non-Aggression Pact with the Jews, p.114|Carta persefahaman Islam; Perjanjian dengan Yahudi"},

{id:"s73",n:73,e:8,y:622.95,ah:1,age:53,pl:"madinah",sc:"masjid",
 w:["Tahun 1 Hijrah","The year 1 AH"],
 t:["Azan disyariatkan","The azan is established"],
 f:["Apabila masjid siap, orang Islam berbincang bagaimana memanggil orang untuk solat. Ada yang mencadangkan loceng seperti orang Nasrani, dan ada yang mencadangkan trompet seperti orang Yahudi.\nAbdullah bin Zaid bin Abd Rabbih bermimpi seorang lelaki mengajarnya lafaz azan. Apabila beliau menceritakannya, Rasulullah ﷺ bersabda bahawa itu mimpi yang benar, dan menyuruhnya mengajar lafaz itu kepada Bilal yang suaranya lebih lantang. Ketika Bilal melaungkan azan, Umar datang dan berkata beliau juga bermimpi perkara yang sama.\nSejak hari itu, azan berkumandang lima kali sehari.",
   "When the masjid was ready, the Muslims discussed how to call people to prayer. Some suggested a bell like the Christians, and some a horn like the Jews.\n'Abdullah ibn Zayd ibn 'Abd Rabbih dreamt that a man taught him the words of the azan. When he told the Prophet ﷺ, he said it was a true dream and told him to teach the words to Bilal, whose voice was stronger. As Bilal called the azan, 'Umar came and said he had seen the same dream.\nFrom that day the azan has been called five times a day."],
 l:[["Syiar Islam mempunyai identiti tersendiri.","The rites of Islam have their own identity."]],
 hd:[{r:"Sunan Abi Dawud 499",m:["Abdullah bin Zaid (r.a.) menceritakan mimpinya tentang lafaz azan.","'Abdullah ibn Zayd (r.a.) told of his dream of the words of the azan."]}],
 p:["bilal","umar"],s:"A New Society Being Built, p.114|Pembinaan Masjid an-Nabawi"},

{id:"s74",n:74,e:8,y:623.2,ah:1,age:53,pl:"madinah",sc:"birth",
 w:["Syawal 1 H","Shawwal 1 AH"],
 t:["Aisyah (r.a.) mula tinggal bersama Baginda","'A'ishah (r.a.) joins his household"],
 f:["Selepas Rasulullah ﷺ menetap di Madinah, Baginda menghantar Zaid bin Harithah dan Abu Rafi' ke Makkah untuk membawa ahli keluarganya: puteri-puterinya Fatimah dan Ummu Kalthum, isterinya Saudah, dan Ummu Aiman. Abdullah bin Abi Bakar pula membawa keluarga Abu Bakar, termasuk Aisyah.\nPada bulan Syawal tahun pertama Hijrah, Aisyah mula tinggal bersama Rasulullah ﷺ di bilik di sisi masjid. Rumah tangga mereka penuh kasih sayang. Bilik Aisyah inilah yang kemudiannya menjadi tempat Baginda wafat dan dimakamkan.",
   "Once settled in Madinah, the Prophet ﷺ sent Zayd ibn Harithah and Abu Rafi' to Makkah to bring his family: his daughters Fatimah and Umm Kulthum, his wife Sawdah, and Umm Ayman. 'Abdullah ibn Abi Bakr brought Abu Bakr's family, including 'A'ishah.\nIn Shawwal of the first year after the Hijrah, 'A'ishah began living with the Prophet ﷺ in a room beside the masjid. Their home was full of love. This same room of 'A'ishah's would later be where he passed away and was buried."],
 l:[["Kasih sayang dalam rumah tangga ialah sunnah Rasulullah ﷺ.","Love at home is the way of the Prophet ﷺ."]],
 p:["aisyah","zaid","fatimah","saudah"],s:"Marriage of the Prophet to 'Aishah, p.82|Secebis ulasan mengenai perkahwinan Rasulullah dengan Aisyah"},

{id:"s75",n:75,e:8,y:623.3,ah:1,age:53,pl:"madinah",sc:"hoof",
 w:["Ramadan 1 H dan seterusnya","Ramadan 1 AH onwards"],
 t:["Izin berperang & ekspedisi awal","Permission to fight and the first expeditions"],
 f:["Quraisy terus mengancam orang Islam di Madinah, merampas harta Muhajirin di Makkah dan bersekutu dengan Abdullah bin Ubai. Selama tiga belas tahun di Makkah, orang Islam diperintah bersabar dan tidak membalas. Kini Allah mengizinkan mereka berperang kerana mereka telah dizalimi.\nRasulullah ﷺ menghantar pasukan-pasukan kecil untuk mengawasi laluan kafilah Quraisy ke Syam dan membuat perjanjian dengan kabilah sekitar. Antaranya Sariyah Saif al-Bahr di bawah Hamzah pada Ramadan 1 H, dan Ghazwah al-Abwa' atau Waddan pada Safar 2 H, ekspedisi pertama yang diketuai sendiri oleh Baginda. Kebanyakannya berakhir tanpa pertempuran.",
   "Quraysh kept threatening the Muslims in Madinah, seizing the Muhajirin's property in Makkah and allying with 'Abdullah ibn Ubayy. For thirteen years in Makkah the Muslims had been told to be patient and not fight back. Now Allah permitted them to fight, because they had been wronged.\nThe Prophet ﷺ sent small units to watch the Quraysh caravan routes to Syria and made treaties with the tribes around. Among them was the Saif al-Bahr mission under Hamzah in Ramadan 1 AH, and the Abwa' or Waddan expedition in Safar 2 AH, the first he led himself. Most ended without fighting."],
 l:[["Peperangan dalam Islam bertujuan menolak kezaliman, bukan menyerang tanpa sebab.","Fighting in Islam is to repel injustice, not to attack without cause."]],
 ay:[{r:"al-Hajj 22:39",ar:"أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا ۚ وَإِنَّ اللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ",m:["Diizinkan (berperang) bagi orang yang diperangi kerana mereka telah dizalimi, dan sesungguhnya Allah Maha Kuasa menolong mereka.","Permission is given to those who are fought against, because they have been wronged, and Allah is surely able to help them."]}],
 p:["hamzah"],s:"Pre-Badr Missions and Invasions, p.114|Keizinan Allah kepada kaum muslimin untuk mengangkat senjata; Ghazwah dan sariyah sebelum peperangan Badar"},

{id:"s76",n:76,e:8,m:1,y:624.1,ah:2,age:54,pl:"madinah",sc:"kaabah",
 w:["Syaaban 2 H (Februari 624)","Sha'ban 2 AH (February 624)"],
 t:["Kiblat bertukar ke Kaabah","The qiblah turns to the Kaabah"],
 f:["Selama kira-kira enam belas atau tujuh belas bulan di Madinah, orang Islam bersolat menghadap Baitulmaqdis. Rasulullah ﷺ sangat berharap kiblat dikembalikan ke Kaabah, rumah yang dibina Nabi Ibrahim (a.s.), dan Baginda sering menengadah ke langit.\nPada bulan Syaaban tahun kedua Hijrah, Allah menurunkan ayat yang memerintahkan Baginda menghadap Masjidil Haram. Satu kumpulan sahabat yang sedang rukuk di masjid lain mendengar berita itu dan terus berpusing ke arah Kaabah dalam solat mereka.\nPertukaran ini menguji siapa yang benar-benar mengikut Rasul, dan menjadikan umat Islam mempunyai arah yang tersendiri.",
   "For about sixteen or seventeen months in Madinah, the Muslims prayed facing Jerusalem. The Prophet ﷺ longed for the qiblah to return to the Kaabah, the house built by Ibrahim (a.s.), and he would often look up at the sky.\nIn Sha'ban of the second year after the Hijrah, Allah revealed the verse commanding him to face the Sacred Masjid. A group of companions bowing in prayer in another masjid heard the news and turned toward the Kaabah in the middle of their prayer.\nThe change tested who truly followed the Messenger, and gave the Muslims a direction of their own."],
 k:["Dahulu orang Islam bersolat menghadap Masjid al-Aqsa. Nabi ﷺ sangat mahu menghadap Kaabah. Allah memperkenankannya, dan sejak itu kita semua bersolat menghadap Kaabah di Makkah.","At first the Muslims prayed facing Masjid al-Aqsa. The Prophet ﷺ dearly wished to face the Kaabah. Allah granted it, and since then we all pray facing the Kaabah in Makkah."],
 l:[["Allah memperkenankan harapan hati Rasul-Nya.","Allah answered the heartfelt hope of His Messenger."],["Taat segera apabila perintah sampai.","Obey at once when a command arrives."]],
 ay:[{r:"al-Baqarah 2:144",ar:"قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ",m:["Kami melihat wajahmu sering menengadah ke langit, maka Kami palingkan engkau ke kiblat yang engkau sukai. Palingkanlah wajahmu ke arah Masjidil Haram.","We have seen you turning your face to the sky, so We will turn you to a qiblah that pleases you. Turn your face toward the Sacred Masjid."]}],
 hd:[{r:"Sahih al-Bukhari 40",m:["Al-Bara' (r.a.) meriwayatkan bahawa mereka bersolat menghadap Baitulmaqdis enam belas atau tujuh belas bulan sebelum kiblat bertukar.","Al-Bara' (r.a.) narrated that they prayed toward Jerusalem for sixteen or seventeen months before the qiblah changed."]}],
 s:"Pre-Badr Missions and Invasions, p.114|"},

{id:"s77",n:77,e:8,y:624.15,ah:2,age:54,pl:"madinah",sc:"crescent",
 w:["Tahun 2 Hijrah","The year 2 AH"],
 t:["Puasa Ramadan & zakat fitrah difardukan","Ramadan fasting and zakat al-fitr become obligatory"],
 f:["Pada tahun kedua Hijrah, Allah memfardukan puasa bulan Ramadan, dan zakat fitrah diwajibkan sebelum solat hari raya. Zakat harta dengan kadar-kadarnya juga ditetapkan sekitar masa ini.\nHikmahnya besar: puasa mendidik jiwa supaya bertakwa, dan zakat fitrah membersihkan orang yang berpuasa daripada perkataan sia-sia serta memberi makan kepada orang miskin pada hari raya. Ramadan pertama ini juga menyaksikan Perang Badar.",
   "In the second year after the Hijrah, Allah made the fast of Ramadan obligatory, and zakat al-fitr was required before the Eid prayer. Zakat on wealth, with its set rates, was also established around this time.\nThe wisdom is great: fasting trains the soul in piety, and zakat al-fitr purifies the one who fasted from idle words and feeds the poor on the day of Eid. This first Ramadan also saw the Battle of Badr."],
 l:[["Ibadah dalam Islam datang berperingkat-peringkat.","The acts of worship in Islam came in stages."],["Hari raya ialah hari semua orang, termasuk yang miskin, bergembira.","Eid is a day for everyone, the poor included, to rejoice."]],
 ay:[{r:"al-Baqarah 2:183",ar:"يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ",m:["Wahai orang beriman, diwajibkan ke atas kamu berpuasa sebagaimana diwajibkan ke atas orang sebelum kamu, supaya kamu bertakwa.","O you who believe, fasting is prescribed for you as it was prescribed for those before you, so that you may become mindful of Allah."]}],
 s:"The Battle of Badr, p.114|Peperangan Badar al-Kubra"}
);
